SELECT
COUNT ( id ) AS "customer_added_count",
create_time :: DATE as "day"
FROM
application_chat_user_stats

    APPLICATION_ID = #{appId}

    AND (chat_user_type IS NULL OR chat_user_type NOT IN ('APPLICATION_API_KEY', 'TRIGGER_USER'))

        and  TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startTime} 


        and  TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endTime} 


GROUP BY "day";

